import {renderTrainInfo136} from './train-info136.js?v=264';
export function mountInfoShell139(host,onGuideReady=()=>{}){
 const legacy=document.createElement('div');legacy.id='info-documents-host144';legacy.append(...host.childNodes);
 host.innerHTML=`<nav class="info-tabs139" role="tablist" aria-label="Información del simulador"><button id="info-tab-portal139" role="tab" aria-selected="true" aria-controls="info-portal139" tabindex="0">Portal técnico</button><button id="info-tab-guide139" role="tab" aria-selected="false" aria-controls="info-guide139" tabindex="-1">Partes, cálculos y prácticas</button><button id="info-tab-documents144" role="tab" aria-selected="false" aria-controls="info-documents144" tabindex="-1">Documentos y fuentes</button><button id="info-tab-original200" role="tab" aria-selected="false" aria-controls="info-original200" tabindex="-1">HTML original · sin editar</button></nav><section id="info-portal139" role="tabpanel" aria-labelledby="info-tab-portal139"><iframe class="info-frame139" title="Portal técnico de material rodante, energía y frenado" sandbox="allow-scripts allow-popups allow-popups-to-escape-sandbox allow-downloads" referrerpolicy="no-referrer"></iframe></section><section id="info-guide139" role="tabpanel" aria-labelledby="info-tab-guide139" hidden><div id="info-guide-host139"></div></section><section id="info-documents144" role="tabpanel" aria-labelledby="info-tab-documents144" hidden></section><section id="info-original200" role="tabpanel" aria-labelledby="info-tab-original200" hidden><p>Documento original, conservado sin cambios. Sus estilos y gráficas requieren internet; el asistente del documento no está conectado a una API.</p><p><a href="./technical-portal/documento-aportado.html" target="_blank" rel="noopener">Abrir original en otra pestaña ↗</a> · <a href="./technical-portal/documento-aportado.html" download>Descargar HTML original</a></p><iframe class="info-frame139" title="HTML técnico original sin editar" loading="lazy" sandbox="allow-scripts allow-popups allow-popups-to-escape-sandbox allow-downloads" referrerpolicy="no-referrer"></iframe></section>`;
 host.querySelector('#info-documents144').append(legacy); const tabs=[...host.querySelectorAll('[role=tab]')],portal=host.querySelector('#info-portal139'),panel=host.querySelector('#info-guide139'),frame=host.querySelector('iframe');let guide;
 function show(which){
  const showPortal=which==='portal';portal.hidden=!showPortal;panel.hidden=which!=='guide';host.querySelector('#info-documents144').hidden=which!=='documents';host.querySelector('#info-original200').hidden=which!=='original';
  if(which==='original'){const original=host.querySelector('#info-original200 iframe');if(!original.getAttribute('src'))original.src='./technical-portal/documento-aportado.html';}
  for(const [i,tab]of tabs.entries()){const active=i===['portal','guide','documents','original'].indexOf(which);tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;}
  if(showPortal){if(!frame.getAttribute('src'))frame.src='./technical-portal/index.html?v=199';}
  else if(which==='guide'&&!guide){guide=renderTrainInfo136(host.querySelector('#info-guide-host139'));onGuideReady();}
 }
 tabs[0].onclick=()=>show('portal');tabs[1].onclick=()=>show('guide');tabs[2].onclick=()=>show('documents');tabs[3].onclick=()=>show('original');
 for(const tab of tabs)tab.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const index=event.key==='Home'?0:event.key==='End'?tabs.length-1:(tabs.indexOf(tab)+(event.key==='ArrowLeft'?tabs.length-1:1))%tabs.length;show(['portal','guide','documents','original'][index]);tabs[index].focus();});
 return {showPortal(){show('portal');},open(part){show('guide');if(part)requestAnimationFrame(()=>guide.open(part));}};
}
